    const key = {Steam:'steam',Epic_Games:'epic',PlayStation:'playstation',Xbox:'xbox',HiRez_PC:'hirez'}[name];
    mark.title = ui('common.platform.' + key, platform); mark.setAttribute('aria-label', mark.title);
    const image = n('img'); const asset = '/images/icons/platform/Platform_' + name;
    const version = name === 'Epic_Games' ? '?v=4' : '';
    image.src = asset + '.avif' + version; image.alt = ''; image.width = 18; image.height = 18;
